import { useMemo } from "react";
import { useCartStore } from "../store/cartStore";
import { Link, useNavigate } from "react-router-dom";

const API_URL = import.meta.env.VITE_API_BASE_URL;

const CartPage = () => {
  const { cartItems = [], removeItem, updateQuantity } = useCartStore();
  const navigate = useNavigate();

  const total = useMemo(
    () =>
      Array.isArray(cartItems)
        ? cartItems.reduce(
            (sum, item) => sum + (item.price || 0) * (item.quantity || 1),
            0
          )
        : 0,
    [cartItems]
  );

  if (!Array.isArray(cartItems) || cartItems.length === 0) {
    return (
      <div className="max-w-4xl mx-auto p-6 text-center">
        <h1 className="text-3xl font-bold mb-6 text-purple-700">Your Cart</h1>
        <p className="text-gray-500">
          Your cart is empty.{" "}
          <Link to="/" className="text-purple-700 underline">
            Continue Shopping
          </Link>
        </p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto p-6 md:flex gap-6">
      {/* Cart Items */}
      <div className="flex-1 space-y-4">
        <h1 className="text-3xl font-bold mb-6 text-purple-700">Your Cart</h1>
        {cartItems.map((item) => {
          const imageSrc = item?.imageUrl?.startsWith("http")
            ? item.imageUrl
            : `${API_URL}${item?.imageUrl?.startsWith("/") ? item.imageUrl : `/${item?.imageUrl || ""}`}`;

          return (
            <div
              key={item.id || item._id}
              className="flex items-center justify-between p-4 bg-white rounded-lg shadow hover:shadow-md transition"
            >
              <img
                src={imageSrc}
                alt={item?.name || "Product"}
                loading="lazy"
                className="w-24 h-24 object-cover rounded"
                onError={(e) => {
                  e.target.onerror = null;
                  e.target.src =
                    "https://dummyimage.com/100x100/cccccc/000000&text=No+Image";
                }}
              />

              <div className="flex-1 ml-4">
                <h2 className="font-semibold text-lg">{item?.name}</h2>
                <p className="text-gray-500">{item?.category?.name}</p>
                <p className="text-blue-600 font-bold mt-1">Rs {item?.price || 0}</p>
              </div>

              {/* Quantity Controls */}
              <div className="flex items-center gap-2">
                <button
                  className="px-2 py-1 bg-gray-200 rounded hover:bg-gray-300 transition"
                  onClick={() =>
                    updateQuantity(item.id, Math.max(1, (item.quantity || 1) - 1))
                  }
                >
                  -
                </button>
                <span>{item.quantity || 1}</span>
                <button
                  className="px-2 py-1 bg-gray-200 rounded hover:bg-gray-300 transition"
                  onClick={() => updateQuantity(item.id, (item.quantity || 1) + 1)}
                >
                  +
                </button>
              </div>

              <button
                onClick={() => removeItem(item.id)}
                className="ml-4 text-red-600 hover:underline"
              >
                Remove
              </button>
            </div>
          );
        })}
      </div>

      {/* Order Summary Sidebar */}
      <div className="w-full md:w-1/3 bg-white p-6 rounded-lg shadow mt-6 md:mt-0">
        <h2 className="text-2xl font-bold mb-4">Order Summary</h2>
        <div className="flex justify-between mb-2">
          <span>Items ({Array.isArray(cartItems) ? cartItems.length : 0})</span>
          <span>Rs {total}</span>
        </div>
        <div className="border-t my-2"></div>
        <div className="flex justify-between font-bold text-lg">
          <span>Total</span>
          <span>Rs {total}</span>
        </div>
        <button
          onClick={() => navigate("/checkout")}
          className="block w-full mt-6 bg-purple-700 text-white py-3 rounded hover:bg-purple-800 transition font-semibold"
        >
          Proceed to Checkout
        </button>
      </div>
    </div>
  );
};

export default CartPage;
